//! Historical wire evidence from bytes produced by the earlier Go implementation.
//!
//! Rust is authoritative; these vectors are an independent regression oracle, not
//! a compatibility requirement. Tests that encode with Rust and decode with Rust
//! can miss a paired encoder/decoder drift -- for example a reordered field or a
//! `null` emitted where the committed vector contains `""`. Independent committed
//! bytes make that class of regression observable.
//!
//! The vectors in `tests/vectors/go` were generated by `tools/gowirevectors`,
//! which links a sibling historical `scionic-merkletree` checkout through a
//! `replace` directive and calls `Dag.ToJSON()` / `Dag.ToCBOR()` directly.
//!
//! JSON and CBOR are asserted differently because the historical artifacts differ:
//!
//! * Historical `ToJSON` output is byte-stable. `encoding/json` sorts map keys,
//!   while struct fields emit in definition order, so byte-for-byte equality is
//!   useful independent evidence for the selected Rust wire shape.
//! * Historical `ToCBOR` output is not byte-stable. Its `Leafs` map inherits
//!   randomized iteration order; `tools/gowirevectors` recorded `stable=false`
//!   across repeated encodes. Those artifacts are therefore checked for decoded
//!   value equivalence rather than treated as canonical bytes.

mod support;

use scionic_merkletree::Dag;
use std::path::PathBuf;

fn vector(name: &str, extension: &str) -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("vectors")
        .join("go")
        .join(format!("{name}.{extension}"));
    std::fs::read(&path).unwrap_or_else(|error| {
        panic!(
            "missing Go vector {}: {error}. Regenerate with: cd tools/gowirevectors && go run . ../../tests/vectors/go",
            path.display()
        )
    })
}

/// Reports the first byte that differs, with context, instead of dumping 36 KB
/// of base64 into the failure output.
fn assert_bytes_eq(actual: &[u8], expected: &[u8], label: &str) {
    if actual == expected {
        return;
    }
    let offset = actual
        .iter()
        .zip(expected.iter())
        .position(|(a, b)| a != b)
        .unwrap_or_else(|| actual.len().min(expected.len()));
    let start = offset.saturating_sub(70);
    let end_actual = (offset + 70).min(actual.len());
    let end_expected = (offset + 70).min(expected.len());
    panic!(
        "{label}: wire bytes diverge from Go at offset {offset} \
         (rust {} bytes, go {} bytes)\n  rust: ...{}...\n  go:   ...{}...",
        actual.len(),
        expected.len(),
        String::from_utf8_lossy(&actual[start..end_actual]),
        String::from_utf8_lossy(&expected[start..end_expected]),
    );
}

#[test]
fn go_json_vectors_decode_and_reemit_byte_for_byte() {
    for fixture in support::FIXTURES {
        let expected = vector(fixture.name, "json");

        let dag = Dag::from_json(&expected)
            .unwrap_or_else(|error| panic!("{}: Go JSON failed to decode: {error}", fixture.name));

        assert_eq!(
            dag.root().to_string(),
            fixture.root,
            "{}: decoded Go JSON has the wrong root",
            fixture.name
        );
        dag.verify().unwrap_or_else(|error| {
            panic!("{}: decoded Go JSON failed verify: {error}", fixture.name)
        });

        let reemitted = dag
            .to_json()
            .unwrap_or_else(|error| panic!("{}: re-encode failed: {error}", fixture.name));
        assert_bytes_eq(&reemitted, &expected, fixture.name);
    }
}

#[test]
fn go_cbor_vectors_decode_to_the_json_equivalent_dag() {
    for fixture in support::FIXTURES {
        let cbor = vector(fixture.name, "cbor");

        let from_cbor = Dag::from_cbor(&cbor)
            .unwrap_or_else(|error| panic!("{}: Go CBOR failed to decode: {error}", fixture.name));

        assert_eq!(
            from_cbor.root().to_string(),
            fixture.root,
            "{}: decoded Go CBOR has the wrong root",
            fixture.name
        );
        from_cbor.verify().unwrap_or_else(|error| {
            panic!("{}: decoded Go CBOR failed verify: {error}", fixture.name)
        });

        let from_json = Dag::from_json(&vector(fixture.name, "json"))
            .unwrap_or_else(|error| panic!("{}: Go JSON failed to decode: {error}", fixture.name));

        assert_eq!(
            from_cbor, from_json,
            "{}: Go CBOR and Go JSON decoded to different DAGs",
            fixture.name
        );
    }
}

/// The states the reference actually puts on the wire, measured by
/// `tools/gowirevectors` across all six fixtures:
///
/// ```text
/// ContentHash        nil=16 lens={32:26}
/// ClassicMerkleRoot  nil=0  lens={0:26, 32:12, 59:4}
/// Links              nil=0  empty(nonNil)=26 nonEmpty=16
/// AdditionalData     nil=0
/// StoredProofs       nil=0  empty(nonNil)=42   (omitempty -> absent on the wire)
/// Proof.Siblings     nil=0  lens={}
/// ```
///
/// `ClassicMerkleRoot` is the one field that genuinely carries a non-nil *empty*
/// byte string, 26 times: leaf nodes with no children. Go emits `""` in JSON and
/// `0x40` in CBOR for it, never `null`/`0xf6`. `Links` is likewise never nil,
/// because `ToSerializable` always does `make([]string, len(leaf.Links))`.
///
/// A single Go document carries both states at once: `"ContentHash": null` for
/// a nil slice, and `"ClassicMerkleRoot": ""` for a non-nil empty one. This test
/// pins that coexistence, so collapsing either direction fails here under a
/// clear name rather than as an opaque byte offset in the round-trip test above.
#[test]
fn go_empty_and_absent_wire_states_are_preserved_exactly() {
    let expected = vector("flat_directory", "json");
    let text = String::from_utf8(expected.clone()).expect("Go JSON is valid UTF-8");

    assert!(
        text.contains("\"ClassicMerkleRoot\": \"\""),
        "the Go vector should contain an empty-string ClassicMerkleRoot"
    );
    assert!(
        text.contains("\"Links\": []"),
        "the Go vector should contain an empty Links array"
    );
    assert!(
        text.contains("\"AdditionalData\": {}"),
        "the Go vector should contain an empty AdditionalData object"
    );
    assert!(
        !text.contains("stored_proofs"),
        "a full DAG carries no proofs, and Go's omitempty drops the key entirely"
    );
    // Go emits both states in this one document: `null` for the 16 nil
    // ContentHash fields (directory and root leaves hold no content), and `""`
    // for the 26 non-nil empty ClassicMerkleRoot fields. Modelling ContentHash
    // as a plain byte vector would write "" where Go writes null; modelling
    // ClassicMerkleRoot as an Option would write null where Go writes "". Both
    // mistakes survive a self round-trip. Neither survives this.
    assert!(
        text.contains("\"ContentHash\": null"),
        "Go writes null for a nil ContentHash, distinct from an empty string"
    );

    let dag = Dag::from_json(&expected).expect("Go JSON decodes");
    let reemitted = String::from_utf8(dag.to_json().expect("re-encode")).expect("valid UTF-8");

    assert!(
        reemitted.contains("\"ClassicMerkleRoot\": \"\""),
        "empty ClassicMerkleRoot must survive as an empty string, not null"
    );
    assert!(
        reemitted.contains("\"Links\": []"),
        "empty Links must survive as an empty array, not null"
    );
    assert!(
        !reemitted.contains("stored_proofs"),
        "an empty proof map must stay absent, matching Go's omitempty"
    );
    assert!(
        reemitted.contains("\"ContentHash\": null"),
        "a nil ContentHash must survive as null, never as an empty string"
    );
}
